import React from "react";
import "../styles/HomePage.css";
import HomePageNavBar from "./HomePageNavBar.jsx";
import LogInPage from "../pages/LogInPage.jsx";

export default function HomePage() {
  return (
    <div className="home-page">
      <HomePageNavBar />

      <main className="content">
        <div className="banner">
          <h2>Welcome to the SOEN 341 Event Platform</h2>
          <p>
            Our platform allows students and organizers to easily browse, create, 
            and manage campus events.
          </p>

          <a href={LogInPage} className="login-button">Login</a>
        </div>
      </main>
    </div>
  );
}
